class Solution {
  public int[] getModifiedArray(int length, int[][] updates) {
    int[] diff = new int[length + 1];
    for (int[] u : updates) {
      diff[u[0]] += u[2];
      diff[u[1] + 1] -= u[2];
    }
    int[] res = new int[length];
    for (int i = 0, run = 0; i < length; i++) res[i] = run += diff[i];
    return res;
  }
}
